import numpy as np

# For a discrete-time LTI filter H(z), the frequency response is H(e^{jw})
# where w is the normalized frequency (0 to pi).
# A low-pass filter has high gain at w=0 (DC) and low gain at w=pi (Nyquist).

# Let's evaluate each filter at w=0 and w=pi for a specific value of omega (the parameter)
# The parameter omega in the transfer function is a design parameter.
# Let's pick omega = 0.5 as a test value.

def H_A(z, omega):
    return omega**2 / (z**2 + z*(np.sqrt(2)*omega - 2) + (1 - np.sqrt(2)*omega + omega**2))

def H_B(z, omega):
    return omega**2 / (z**4 - z**2*(np.sqrt(2)*omega - 2) + (1 - np.sqrt(2)*omega + omega**2))

def H_C(z, omega):
    return omega**2 / (z**2 - z*(np.sqrt(2)*omega - 2) + (1 - np.sqrt(2)*omega + omega**2))

def H_D(z, omega):
    return omega**2 / (-z**2 - z*(np.sqrt(2)*omega - 2) + (1 - np.sqrt(2)*omega + omega**2))

omega = 0.5
z_dc = 1.0       # w = 0
z_nyq = -1.0     # w = pi

for name, H in [('A', H_A), ('B', H_B), ('C', H_C), ('D', H_D)]:
    h_dc = H(z_dc, omega)
    h_nyq = H(z_nyq, omega)
    print(f"G_{name}: |H(0)| = {abs(h_dc):.4f}, |H(pi)| = {abs(h_nyq):.4f}")
    # Also check at w = pi/2
    z_mid = 1j
    h_mid = H(z_mid, omega)
    print(f"         |H(pi/2)| = {abs(h_mid):.4f}")
    print()

